                            '&.Mui-selected': {
                                bgcolor: 'action.selected',
                                borderColor: 'primary.main',
                                color: 'primary.main',
                                '&:hover': { bgcolor: 'action.selected' },
                            },
                        },
                    }}
                    value={selectedAction.id}
                >
                    {actions.map((action) => (
                        <ActionSelectorButton
                            action={action}
                            context={context}
                            key={action.id}
                            liveStatus={activeActionStatuses[action.id]}
                        />
                    ))}
                </ToggleButtonGroup>
            </Box>
        </Box>
    )
}

